// LexicalAnalysis.cpp : 此文件包含 "main" 函数。程序执行将在此处开始并结束。
//
#include <iostream>
#include <cstring>
#include <fstream>
#include <sstream>
#include <vector>
#include <ctype.h>
#include <set>
#include <iomanip>
#include <map>
using namespace std;


//美化输出
void printTask(const string tip,const string placeholder) {
	int len = 80 - tip.length();
	int left = len / 2;
	int right = len - left;
	cout << "|";
	for (int i = 0; i < left; i++) {
		cout << placeholder;
	}
	cout << tip;
	for (int i = 0; i < right; i++) {
		cout << placeholder;
	}
	cout << "|" << endl;
}
void printTips(const string tip) {
	cout << "|********************************************************************************|" << endl;
	printTask(tip,"*");
	cout << "|********************************************************************************|" << endl;
	cout << endl;
}

//原始源程序文件：非法单词的行列定位需要回到预处理之前的源文件中查找
const string SOURCE_FILE = "./testCpp.txt";

//单词类别信息
struct wtPair{
	int idx;
	int type;
	string value;
	wtPair(int a, int b, string c) :idx(a), type(b), value(c) {}
};

//预处理程序
bool preProcess(const string fileName, const string newFileName) {
	printTips("开始预处理");
	//打开原始源程序文件
	ifstream in(fileName.c_str());
	if (!in) {
		cout << "源程序文件打开失败：" << fileName << endl;
		return false;
	}
	//将源程序整体读入字符缓冲区，后续清洗阶段在此缓冲区上继续加工
	string code = "";
	char ch;
	while (in.get(ch)) {
		code += ch;
	}
	in.close();

	//第一步：删除注释，支持“//”单行注释和可以跨行的“/* */”块注释，
	//其余字符原样保留，交给后面的空白清洗阶段继续处理
	string noComment = "";
	for (unsigned int i = 0; i < code.length(); i++) {
		if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '/') {
			//单行注释：一直跳到行尾，换行符本身保留
			i += 2;
			while (i < code.length() && code[i] != '\n') {
				i++;
			}
			if (i < code.length()) {
				noComment += code[i];
			}
		}
		else if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '*') {
			//块注释：一直跳到配对的“*/”，中途可以跨越任意多行
			i += 2;
			while (i + 1 < code.length() && !(code[i] == '*' && code[i + 1] == '/')) {
				i++;
			}
			i++;//此时i停在“*”上，再前进一位越过“/”，循环的i++负责越过其后
		}
		else {
			noComment += code[i];
		}
	}
	code = noComment;

	//第二步：清洗空白字符，删除回车换行与制表符，并把连续的多个空格压缩成一个
	string cleaned = "";
	for (unsigned int i = 0; i < code.length(); i++) {
		char c = code[i];
		if (c == '\n' || c == '\r' || c == '\t' || c == '\v' || c == '\f') {
			continue;//回车换行、制表符直接丢弃
		}
		if (c == ' ' && !cleaned.empty() && cleaned[cleaned.length() - 1] == ' ') {
			continue;//连续空格只保留第一个
		}
		cleaned += c;
	}
	code = cleaned;

	//将预处理后的源程序以字符流的形式显示出来
	cout << "预处理后的源程序字符流如下：" << endl;
	cout << code << endl << endl;

	//输出到预处理结果文件
	ofstream out(newFileName.c_str());
	if (!out) {
		cout << "预处理结果文件创建失败：" << newFileName << endl;
		return false;
	}
	out << code;
	out.close();
	cout << "预处理结果已保存至：" << newFileName << endl << endl;
	printTips("预处理已完成");
	return true;
}

//判断单词是否是变量名
bool IsIdentifier(const string word) {
	if (word.empty()) {
		return false;
	}
	//首字符只能是字母或者下划线
	if (!isalpha((unsigned char)word[0]) && word[0] != '_') {
		return false;
	}
	//其余字符只能是字母、数字或者下划线
	for (unsigned int i = 1; i < word.length(); i++) {
		if (!isalnum((unsigned char)word[i]) && word[i] != '_') {
			return false;
		}
	}
	return true;
}
//判断单词是否是数字
bool IsNum(const string word) {
	//十进制整数：首位之后的每一个字符都必须是数字
	for (unsigned int i = 1; i < word.length(); i++) {
		if (!isdigit((unsigned char)word[i])) {
			return false;
		}
	}
	return true;
}
//单词-类别对照表，非法单词统一用类别码0表示
static map<string, int> buildWordTypeTable() {
	map<string, int> table;
	table["void"] = 1;
	table["main"] = 2;
	table["int"] = 3;
	table["cout"] = 4;
	table["return"] = 5;
	table["("] = 6;
	table[")"] = 7;
	table["{"] = 8;
	table["}"] = 9;
	table["<<"] = 10;
	table[";"] = 11;
	table[","] = 12;
	table["="] = 13;
	table["*"] = 14;
	table["/"] = 15;
	return table;
}
//判断单词类型
int wtMatch(const string word) {
	static const map<string, int> wordType = buildWordTypeTable();
	//先查关键字与界符运算符表
	map<string, int>::const_iterator it = wordType.find(word);
	if (it != wordType.end()) {
		return it->second;
	}
	//再判断标识符与十进制整数
	if (IsIdentifier(word)) {
		return 16;
	}
	if (IsNum(word)) {
		return 17;
	}
	//都不满足则是非法单词
	return 0;
}
//在原始源程序中逐行定位非法单词，返回“第x行第y列”形式的位置描述
string findError(const string fileName, const string value) {
	ostringstream position;
	if (value.empty()) {
		return position.str();
	}
	ifstream in(fileName.c_str());
	if (!in) {
		return position.str();
	}
	string line;
	int row = 1;
	while (getline(in, line)) {
		//同一行中该单词可能出现多次，逐个定位
		string::size_type col = line.find(value);
		while (col != string::npos) {
			position << "第" << row << "行第" << col << "列";
			col = line.find(value, col + 1);
		}
		row++;
	}
	in.close();
	return position.str();
}
bool mainProcess(const string fileName, const string fileNameProcessed) {
	(void)fileNameProcessed;
	//读入预处理之后的源程序字符流
	ifstream in(fileName.c_str());
	if (!in) {
		cout << "预处理结果文件打开失败：" << fileName << endl;
		return false;
	}
	string code = "", line;
	while (getline(in, line)) {
		code += line;
	}
	in.close();

	//扫描字符流进行分词，按出现顺序记录<序号,类别码,值>
	vector<wtPair> wtSeq;
	string word = "";
	int idx = 0;
	for (unsigned int i = 0; i < code.length(); i++) {
		char c = code[i];
		if (isalnum((unsigned char)c) || c == '_') {
			word += c;//字母、数字、下划线归入当前单词
			continue;
		}
		//遇到分隔符，先把已经累积起来的单词收尾
		if (!word.empty()) {
			idx++;
			wtSeq.push_back(wtPair(idx, wtMatch(word), word));
			word = "";
		}
		if (isspace((unsigned char)c)) {
			continue;//空白只起分隔作用，本身不是单词
		}
		//界符与运算符自身也是一个单词，“<<”需要整体识别
		string symbol(1, c);
		if (c == '<' && i + 1 < code.length() && code[i + 1] == '<') {
			symbol = "<<";
			i++;
		}
		idx++;
		wtSeq.push_back(wtPair(idx, wtMatch(symbol), symbol));
	}
	//字符流末尾可能还剩下一个单词
	if (!word.empty()) {
		idx++;
		wtSeq.push_back(wtPair(idx, wtMatch(word), word));
	}

	//输出单词-类别表：合法单词留在表中显示，非法单词跳过并收集到出错序列
	vector<wtPair> errorSeq;
	cout << setw(8) << "单词序号" << setw(12) << "单词类别" << setw(12) << "单词" << endl;
	for (unsigned int i = 0; i < wtSeq.size(); i++) {
		if (wtSeq[i].type <= 0) {
			errorSeq.push_back(wtSeq[i]);
			continue;
		}
		cout << setw(8) << wtSeq[i].idx << setw(12) << wtSeq[i].type << setw(12) << wtSeq[i].value << endl;
	}
	return true;
}


int main()
{
	string fileName = "./testCpp.txt";
	string afterPreProcess = "./afterPreProcess.txt";
	string processed = "./processed.txt";
	printTips("开始词法分析");
	if (preProcess(fileName, afterPreProcess)) {
		if (mainProcess(afterPreProcess, processed)) {
			printTips("词法分析已完成");
		}
	}
}

